function Replace-Shape($sh){
  if($sh.Type -eq 6){for($i=1;$i -le $sh.GroupItems.Count;$i++){Replace-Shape $sh.GroupItems.Item($i)};return}
  try{
    if($sh.HasTextFrame -eq -1 -and $sh.TextFrame.HasText -eq -1){
      $t=$sh.TextFrame.TextRange.Text.Trim()
      if($m.ContainsKey($t)){$sh.TextFrame.TextRange.Text=$m[$t]}
    }
  }catch{}
  try{if($sh.HasTable -eq -1){for($r=1;$r -le $sh.Table.Rows.Count;$r++){for($c=1;$c -le $sh.Table.Columns.Count;$c++){Replace-Shape $sh.Table.Cell($r,$c).Shape}}}}catch{}
}
$src=(Resolve-Path -LiteralPath $Source).Path
$out=[System.IO.Path]::GetFullPath($Output)
$app=New-Object -ComObject PowerPoint.Application
try{
  $p=$app.Presentations.Open($src,$false,$false,$false)
  try{
    foreach($s in $p.Slides){for($i=1;$i -le $s.Shapes.Count;$i++){Replace-Shape $s.Shapes.Item($i)}}
    $p.SaveAs($out,24)
  }finally{$p.Close()}
}finally{$app.Quit()}
Get-Item -LiteralPath $out | Select-Object FullName,Length

